#!/usr/bin/env python3
"""Build research/timeline-master.md from the `timeline` table in notes.db (schema section 11 rows of every note).

Usage: python3 tools/build_timeline.py [--dry] [--contradictions]
--contradictions writes research/timeline-contradictions.md instead: the master page's two generated tables (rows whose Agreement
contradicts another note's date; rows that drift) as a page of their own, so `ledger present` regenerates them as a step. The dated
pages research/timeline-contradictions-2026-09-27.md and research/timeline-consolidated-*.md are agent-written and not touched.
The page lists every dated event in the database in chronological order (sort_key; `?` rows last), grouped by year,
with the speaker, basis, chain, source note and the note's own Agreement verdict; then the contradictions and drifts
as separate tables. It is derived: edit the notes' `## Dated timeline` sections, rebuild notes.db, rerun this.
The consolidated timeline (research/timeline-consolidated.md) is written by agents from this page, not by this script."""
import sqlite3, re, os, sys, datetime
import sys as _sys; _T = os.path.dirname(os.path.abspath(__file__)); _sys.path.insert(0, _T) if _T not in _sys.path else None   # the ledger package beside this tool
from ledger.paths import root as _project_root; ROOT = _project_root()   # $LEDGER_ROOT, else the nearest ledger.toml at or above the working folder, else this tools' project (2026-10-22)
db = os.path.join(ROOT, "notes.db"); out = os.path.join(ROOT, "research", "timeline-master.md")
sys.path.insert(0, os.path.join(ROOT, "tools")); from ledger import notes as LN   # the parser library (tools/ledger/notes.py, phase 2)
import packload   # the short labels are display settings (pack.toml [display.index.short_labels]; phase 5, 2026-10-22)
SHORT = packload.short_labels()
con = sqlite3.connect(db); cur = con.cursor()
rows = cur.execute("""SELECT t.video, t.n, t.date_stated, t.sortable, t.sort_key, t.approx, t.event, t.speaker_basis, t.chain, t.link, t.agreement, t.agreement_kind, v.title
                      FROM timeline t JOIN videos v ON v.id = t.video ORDER BY t.sort_key, t.video, t.n_sort""").fetchall()
def label(vid, title):
    f = vid + ".md"; return SHORT.get(f) or (title[:40] if title else vid)
def ndir(slug):
    """Folder of a note: books/ for book notes, videos/ otherwise (2026-09-28)."""
    return "books" if os.path.exists(os.path.join(ROOT if "ROOT" in globals() else ".", "books", slug + ".md")) else "videos"
def esc(s):
    s = (s or "").replace("|", "/").replace("\n", " ").strip()
    # links copied from a note are relative to videos/; this page lives in research/
    return re.sub(r"\]\((?!\.\./|https?://|research/)([A-Za-z0-9_.-]+)\.md", lambda m: "](../" + ndir(m.group(1)) + "/" + m.group(1) + ".md", s)
if "--dry" in sys.argv:
    print(len(rows), "timeline rows from", len({r[0] for r in rows}), "notes"); sys.exit()
today = datetime.date.today().isoformat()
L = [f"# Master timeline (every dated event in the database)", "",
     "| Field | Value |", "|---|---|",
     f"| **Kind** | derived page, generated by `tools/build_timeline.py` from the `timeline` table (schema section 11 sections of every note); do not edit by hand |",
     f"| **Rows** | {len(rows)} dated events from {len({r[0] for r in rows})} notes; {sum(1 for r in rows if r[5])} anchors approximate or inferred (`~`); {sum(1 for r in rows if r[11]=='contradicts')} rows contradict another note's date; {sum(1 for r in rows if r[11]=='drifts')} drift |",
     f"| **Built** | {today} |",
     "| **How to read** | One row per telling: the same event told by three speakers appears three times, so agreement and disagreement are visible side by side. `Sortable` is the note's ISO anchor (`~` approximate); `Agreement` is the note's own verdict against the database at the time it was written. The consolidated timeline (research/timeline-consolidated.md) resolves clusters into one most-likely date with reasoning. |",
     "| **Related** | [through-lines](through-lines-2026-09-26.md) (the thread timelines), [leads register](leads-and-inferences.md) (every contradiction is a lead), [relations register](relations-register.md) |", "",
     "## Chronological", ""]
year = None
for vid, n, ds, sortable, key, approx, event, sb, chain, link, agr, ak, title in rows:
    if key.startswith("9999999999"): y = "Undated (no anchor on the recording)"
    else:
        yr = int(key[:10]) - 1_000_000_000
        if yr <= -100000: y = f"{-yr // 1000000} million years ago" if yr <= -1000000 else f"{-yr // 1000} thousand years ago"
        else: y = f"{-yr} BC" if yr < 0 else (f"{yr // 100 * 100}s" if yr < 1900 else str(yr))
    if y != year:
        year = y; L += ["", f"### {year}", "", "| Sortable | Date (as stated) | Event | Speaker, basis (time) | Chain | Source note (row) | Agreement |", "|---|---|---|---|---|---|---|"]
    L.append(f"| {esc(sortable)} | {esc(ds)} | {esc(event)} | {esc(sb)} | {esc(chain)} | [{esc(label(vid, title))}](../{ndir(vid)}/{vid}.md) timeline {n} | {esc(agr)} |")
C = []   # the generated contradictions and drifts: the master page's last two sections, and the whole of the --contradictions page
for kind, title in (("contradicts", "Contradictions (the note's date against another note's)"), ("drifts", "Drifts (same event, dates or details that differ without contradiction)")):
    sub = [r for r in rows if r[11] == kind]
    C += ["", f"## {title}", "", f"{len(sub)} rows.", "", "| Sortable | Event | Source note (row) | Agreement |", "|---|---|---|---|"]
    for vid, n, ds, sortable, key, approx, event, sb, chain, link, agr, ak, t in sub:
        C.append(f"| {esc(sortable)} | {esc(event)} | [{esc(label(vid, t))}](../{ndir(vid)}/{vid}.md) timeline {n} | {esc(agr)} |")
if "--contradictions" in sys.argv:
    cout = os.path.join(ROOT, "research", "timeline-contradictions.md")
    H = ["# Timeline contradictions and drifts (generated)", "", "| Field | Value |", "|---|---|",
         "| **Kind** | derived page, generated by `tools/build_timeline.py --contradictions` from the `timeline` table; do not edit by hand |",
         f"| **Rows** | {sum(1 for r in rows if r[11] == 'contradicts')} rows contradict another note's date; {sum(1 for r in rows if r[11] == 'drifts')} drift; of {len(rows)} dated events |",
         f"| **Built** | {today} |",
         "| **How to read** | One row per telling whose own Agreement cell says it contradicts or drifts from another note's date, as the note recorded it when written. The same two tables close the master timeline. The assessed contradictions (what each side says and what would settle it) are agent-written: the dated contradictions page and the consolidated era pages. |",
         "| **Related** | [master timeline](timeline-master.md); [consolidated timelines](timeline-consolidated.md); [leads register](leads-and-inferences.md) |"]
    LN.write_text(cout, "\n".join(H + C) + "\n"); print("wrote", os.path.relpath(cout, ROOT), sum(1 for r in rows if r[11] in ("contradicts", "drifts")), "rows"); sys.exit()
L += C
LN.write_text(out, "\n".join(L) + "\n"); print("wrote", os.path.relpath(out, ROOT), len(rows), "rows")
